INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(60993, 0, 0, 'My brother Darnir was a powerful warrior, and well respected amongst those he served with. He traveled to these far lands with our family axe, and made a name for himself in the battles with the Horde during the Third War.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66517'),
(60993, 1, 0, 'A truce was established between Horde and Alliance as both factions set to head toward Hyjal. My brother would be one of the last few casualties in this conflict, as a foul orc named \'Scartusk\' ambushed him, and took our family axe as his own...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66518'),
(60993, 2, 0, 'This orc breathes today, pardoned by the Horde, and still wielding the axe my brother carried, an heirloom to our family. I desire revenge, above all else.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66519'),
(60471, 0, 0, 'Corruption within Stonetalon? It does not surprise me, even here in tranquil Ashenvale, many of the native species have begun to show signs of aggression. The furbolg are the most obvious of this.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66521'),
(60471, 1, 0, 'Once our ally, the furbolg have become an enemy, attacking at sight and not hesitating to start conflict. Many druids say that nature itself is adapting to the conflict, becoming more hostile and secluded as a means to protect themselves. This could be the case in Stonetalon.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66522'),
(60471, 2, 0, 'Though here in Ashenvale, there is something else rooted deep, clawing at the foundations of all we hold sacred. I do not know what, but I can sense it...', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66523'),
(60471, 3, 0, 'That is all I know, I hope it may be of use to Maloran, we defenders of nature must keep vigilant.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66524'),
(61001, 10, 0, 'Without your effort we would have had to start fresh all over again, those blasted buzzards ruin everything!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66464'),
(61006, 10, 0, 'UP UP AND AWAY!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66520'),
(60998, 10, 0, 'I thank you for traveling as you have. The information you have brought will prove valueable. It is up to me to find the root of the troubles now.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66525'),
(61024, 10, 0, 'You make this old man proud, kid... Not only did you take over those oilfields like it was your own backyard, but you\'ve proudly delivered it into the Union\'s hands, with employees at that. That\'s right, some of the survivors even agreed to join us! You\'ve made our little town just a bit safer, well as safe as it could be!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66466');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9060993, 'I\'ve known Whitepeak ever since my time serving Ironforge.\n\nI\'m certain he could use my experience and expertise out here, especially so far from home.', 'I\'ve known Whitepeak ever since my time serving Ironforge.\n\nI\'m certain he could use my experience and expertise out here, especially so far from home.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9060993, 9060993);
